  'lramp_c02',
  'Current suicide plan, rehearsals and/or preparation',
  'radio',
  'text',
  120,
  true,
  true,
  'C. Risk factors',
  'Acute risk factors',
  NULL,
  '{"key":"lramp_b1","in":["yes"]}'::jsonb,
  NULL,
  NULL
FROM assessment_definitions d
WHERE d.assessment_code = 'LRAMP'
ON CONFLICT (element_key) DO NOTHING;

INSERT INTO assessment_options (
  assessment_element_id,
  assessment_definition_id,
  option_label,
  option_value,
  score_value,
  display_order
)
SELECT
  e.assessment_element_id,
  d.assessment_definition_id,
  'Not reported / Not observed',
  'not_reported',
  0,
  1
FROM assessment_elements e
JOIN assessment_definitions d
  ON d.assessment_definition_id = e.assessment_definition_id
WHERE e.element_key = 'lramp_c02'
  AND d.assessment_code = 'LRAMP'
  AND NOT EXISTS (
    SELECT 1
    FROM assessment_options o
    WHERE o.assessment_element_id = e.assessment_element_id
      AND o.option_value = 'not_reported'
  );

