  display_order,
  is_required,
  is_active,
  group_label,
  subgroup_label,
  parent_element_key,
  show_when_json,
  required_group_key,
  help_text
)
SELECT
  d.assessment_definition_id,
  'lramp_c09',
  'Severe loss of interest or pleasure (anhedonia)',
  'radio',
  'text',
  190,
  true,
  true,
  'C. Risk factors',
  'Acute risk factors',
  NULL,
  '{"key":"lramp_b1","in":["yes"]}'::jsonb,
  NULL,
  NULL
FROM assessment_definitions d
WHERE d.assessment_code = 'LRAMP'
ON CONFLICT (element_key) DO NOTHING;

